  "privacy.whereBody": "प्रामुख्याने तुमच्या डिव्हाइसवर (स्थानिक स्टोरेज). क्लाउड सिंक सक्षम असताना Supabase मध्ये वैकल्पिकरित्या (विश्रांती एनक्रिप्ट केलेले, प्रति वापरकर्ता वेगळे)",
  "privacy.notTitle": "आम्ही काय करत नाही",
  "privacy.notBody": "आम्ही तुमचा डेटा विकत नाही. आम्ही क्रेडिट ब्युरोसह सामायिक करत नाही. आम्ही जाहिरातींसाठी डेटा वापरत नाही. Razorpay पेमेंट हाताळते — Perovo कधीही तुमचे कार्ड तपशील पाहत नाही.",
