  "plans.currentBadge": "चालू",
  "sync.accountSyncBullet": "साइन इन केल्यावर खाते सेटिंग्ज (नाव, शहर, उत्पन्न) तुमच्या Perovo खात्याशी सिंक करा — प्रत्येकासाठी विनामूल्य.",
  "sync.dataBackupPaidBullet": "पेरोवो क्लाउड डेटा बॅकअपसाठी बिले, कर्ज, मालमत्ता आणि करारांना Pro किंवा Power आवश्यक आहे.",
  "sync.backupBullet": "आता बॅक अप तुमचा वर्तमान डेटा Supabase वर सेव्ह करतो.",
  "sync.restoreBullet": "रिस्टोअर हे डिव्हाइस तुमच्या शेवटच्या सेव्ह केलेल्या बॅकअपसह बदलते.",
  "sync.autoBullet": "तुम्ही संपादित केल्यानंतर (सक्षम असताना) ऑटो-बॅकअप काही सेकंद चालतो.",
  "sync.restoreOnLoginBullet": "नवीन फोनवर किंवा रीसेट केल्यानंतर साइन इन करा — तुम्ही सुरू ठेवण्यापूर्वी आम्ही तुमचा नवीनतम बॅकअप ऑफर करतो.",
