  "wealthDetail.property.holdGoodDetail": "खरेदी महागाई आणि ठराविक शहराच्या बेंचमार्कला मागे टाकते तेव्हापासून वाढ. जोपर्यंत तुम्हाला तरलतेची गरज नाही तोपर्यंत होल्डिंगचा विचार करा.",
