  "wealthDetail.property.holdNeutralDetail": "तुम्ही केव्हा खरेदी केली आणि कोणत्या किंमतीला CAGR अनलॉक करायचा ते एंटर करा, महागाई-समायोजित परतावा आणि मार्गदर्शन ठेवा.",
  "wealthDetail.property.holdModerate": "ठेवण्यासारखे - माफक वास्तविक नफा",
  "wealthDetail.property.holdModerateDetail": "नाममात्र वाढ चक्रवाढ आधारावर महागाईला मागे टाकते, परंतु वास्तविक परतावा मध्यम असतो. जर तुम्हाला तरलतेची गरज नसेल तर धरा; मजबूत पुनर्गुंतवणूक योजना किंवा लाइफ-इव्हेंट रोख गरजेसाठी केवळ विक्री करणे अर्थपूर्ण आहे.",
