  "wealthDetail.property.outlookMetro": "Metro corridors: infra (metro lines, IT parks) often lifts land values — watch local RERA/project news.",
  "wealthDetail.property.outlookTier2": "Tier-2 cities: industrial corridors and highway links can accelerate appreciation in 5–8 year cycles.",
  "wealthDetail.property.outlookTier3": "Smaller towns: liquidity is lower — favour long holds and verify title before major price revisions.",
  "wealthDetail.property.outlookAreaFallback": "तुमचा परिसर",
  "wealthDetail.property.purchaseThen": "Purchase price (then)",
  "wealthDetail.property.inflationCostToday": "महागाई-समायोजित खर्च (आज)",
  "wealthDetail.property.inflationCostHint": "तुमचे सध्याचे मूल्य नाही — आजच्या रुपयात मूळ खरेदी किती आहे.",
  "wealthDetail.property.narrative.inflationAdjustedCost": "Your ₹{purchase} purchase equals roughly ₹{todayEquivalent} in today's money after {years} years at ~{inflation}% compounded inflation — real growth is measured against that, not the original price alone.",
  "wealthDetail.property.narrative.purchaseDerived": "खरेदी किंमत आपण प्रविष्ट केलेल्या दर × क्षेत्रावरून येते — एकूण चुकीचे दिसत असल्यास संपादित करा वर टॅप करा.",
  "wealthDetail.property.narrative.realReturnExplain": "Nominal CAGR {cagr}% minus ~{inflation}% inflation ≈ {real}% real return per year — property often looks strong in rupee terms while barely beating inflation after costs.",
  "wealthDetail.property.narrative.vsBenchmarkExplain": "Your {cagr}% CAGR vs ~{benchmark}% typical for this city tier ({delta}% difference) — use as a rough peer check, not a buy/sell signal.",
  "wealthDetail.property.narrative.longHoldLiquidity": "लाँग होल्ड्समुळे वेळेची जोखीम कमी होते परंतु भांडवल लॉक करा — विक्रीयोग्य संपत्ती म्हणून हाताळण्यापूर्वी 6-12 महिन्यांचा खर्च इतरत्र ठेवा.",
  "wealthDetail.property.narrative.rentYieldExplain": "Estimated gross rent yield ~{yield}% — compare with FD/PPF after tax; if you live in the property, treat rent savings as implicit yield.",
  "wealthDetail.property.narrative.rentVsIncome": "पूर्णपणे भाड्याने घेतल्यास, एकूण भाडे तुमच्या घोषित मासिक उत्पन्नाच्या ~{pct}% असेल — ते तुमच्या वास्तविक किंवा साध्य करण्यायोग्य भाड्याशी जुळते का ते तपासा.",
  "wealthDetail.property.narrative.valueVsIncome": "ही मालमत्ता आहे ~{multiple}× कागदावरील तुमचे वार्षिक उत्पन्न — एक मोठे केंद्रीकरण; आणीबाणी आणि विविधीकरण नियोजनात घटक.",
  "wealthDetail.property.narrative.highValueTier3Liquidity": "एका लहान शहरात या मूल्यावर, खरेदीदार शोधण्यासाठी काही महिने लागू शकतात — वास्तविक किंमत आणि त्वरित उपलब्ध रोख म्हणून पूर्ण मूल्य मोजणे टाळा.",
  "wealthDetail.property.narrative.highValueTier2Liquidity": "टियर-2 मार्केटसाठी उच्च तिकीट — तुमच्या सांगितलेल्या मूल्यावर द्रुत तरलता गृहीत धरण्यापूर्वी जवळपासच्या अलीकडील नोंदणीकृत विक्रीची पडताळणी करा.",
  "wealthDetail.property.narrative.targetCagrReality": "येथून 12% CAGR चा पाठलाग करण्यासाठी आजच्या गतीने ~{years} अधिक वर्षे लागतील — तुमच्या होल्डिंगने आधीच मजबूत नाममात्र नफा दिला आहे; भविष्यातील परतावा सामान्य होऊ शकतो.",
  "wealthDetail.property.narrative.landHold": "जमीन: सर्वात कमी देखभाल परंतु सर्वात कमी तरलता — 10+ वर्षांच्या क्षितिजांसाठी सर्वोत्तम; सूचीबद्ध करण्यापूर्वी भार, झोनिंग आणि रस्ता रुंदीकरण सूचना तपासा.",
  "wealthDetail.property.narrative.commercialHold": "व्यावसायिक: जागा आणि भाडेकरूची गुणवत्ता स्थानाइतकीच महत्त्वाची आहे — फूटफॉल किंवा लीज अटी कमकुवत झाल्यास पुनर्मूल्यांकन करा.",
  "wealthDetail.property.narrative.residentialHold": "निवासी: स्वयं-वापरामुळे विक्रीचा दबाव कमी होतो; भाड्याने घेतल्यास, भाडेकरूंची उलाढाल आणि सोसायटी देखभाल वाढीचा मागोवा घ्या.",
  "wealthDetail.property.narrative.verifyTitle": "कोणत्याही विक्रीपूर्वी: भार प्रमाणपत्र, मालमत्ता कर पावत्या आणि उत्परिवर्तन स्थिती — येथे विलंब कागदावरील नफा पुसून टाकतो.",
